const listFeed = `-- name: ListFeed :many
SELECT org_id, id, membership_id, category, kind, data, link, group_key, count, items, occurred_at, read_at, emailed_at, expires_at, created_by, created_at, last_modified_by, last_modified_at FROM feed_entries
WHERE org_id = $1 AND membership_id = $2 AND expires_at > now()
  AND ($3::text IS NULL OR category = $3::text)
  AND ($4::timestamptz IS NULL
       OR (occurred_at, id) < ($4::timestamptz, $5::uuid))
ORDER BY occurred_at DESC, id DESC
LIMIT $6
`

type ListFeedParams struct {
	OrgID        uuid.UUID
	MembershipID uuid.UUID
	Category     pgtype.Text
	BeforeAt     pgtype.Timestamptz
	BeforeID     pgtype.UUID
	PageSize     int32
}

func (q *Queries) ListFeed(ctx context.Context, arg ListFeedParams) ([]FeedEntry, error) {
	rows, err := q.db.Query(ctx, listFeed,
		arg.OrgID,
		arg.MembershipID,
		arg.Category,
		arg.BeforeAt,
		arg.BeforeID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []FeedEntry{}
	for rows.Next() {
		var i FeedEntry
		if err := rows.Scan(
			&i.OrgID,
			&i.ID,
			&i.MembershipID,
			&i.Category,
			&i.Kind,
			&i.Data,
			&i.Link,
			&i.GroupKey,
			&i.Count,
			&i.Items,
			&i.OccurredAt,
			&i.ReadAt,
			&i.EmailedAt,
			&i.ExpiresAt,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.LastModifiedBy,
			&i.LastModifiedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

