const orgsWithFeed = `-- name: OrgsWithFeed :many
SELECT DISTINCT org_id FROM feed_entries WHERE expires_at <= now()
UNION
SELECT DISTINCT org_id FROM devices WHERE last_seen_at < now() - interval '90 days'
LIMIT 5000
`

// global: the orgs the daily purge visits.
func (q *Queries) OrgsWithFeed(ctx context.Context) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, orgsWithFeed)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var org_id uuid.UUID
		if err := rows.Scan(&org_id); err != nil {
			return nil, err
		}
		items = append(items, org_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

